#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<long long> value(n);
    for (int i = 0; i < n; i++) cin >> value[i];
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i + 1;
    sort(order.begin(), order.end(), [&](int a, int b) { return value[a - 1] < value[b - 1]; });
    long long total = n;
    int i = 0;
    while (i < n) {
        int j = i;
        long long x = value[order[i] - 1];
        while (j < n && value[order[j] - 1] == x) j++;
        for (int k = i; k < j; k++) {
            int v = order[k];
            for (int w : adj[v]) {
                if (value[w - 1] <= x) unite(v, w);
            }
        }
        map<int, long long> count;
        for (int k = i; k < j; k++) count[findRoot(order[k])]++;
        for (const auto& entry : count) total += entry.second * (entry.second - 1) / 2;
        i = j;
    }
    cout << total << "\n";

    return 0;
}

