import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] value = new long[(int) n];
        for (int i = 0; i < value.length; i++) value[i] = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) {
            adj.get((int) e[0]).add((int) e[1]);
            adj.get((int) e[1]).add((int) e[0]);
        }
        parent = new int[nodes + 1];
        sizes = new int[nodes + 1];
        for (int v = 0; v <= nodes; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        Integer[] order = new Integer[nodes];
        for (int i = 0; i < nodes; i++) order[i] = i + 1;
        Arrays.sort(order, (a, b) -> Long.compare(value[a - 1], value[b - 1]));
        long total = nodes;
        int i = 0;
        while (i < nodes) {
            int j = i;
            long x = value[order[i] - 1];
            while (j < nodes && value[order[j] - 1] == x) j++;
            for (int k = i; k < j; k++) {
                int v = order[k];
                for (int w : adj.get(v)) {
                    if (value[w - 1] <= x) unite(v, w);
                }
            }
            Map<Integer, Long> count = new HashMap<>();
            for (int k = i; k < j; k++) count.merge(findRoot(order[k]), 1L, Long::sum);
            for (long c : count.values()) total += c * (c - 1) / 2;
            i = j;
        }
        System.out.println(total);
    }
}
